// Quote Walk v2 operator receipt bridge.
// The database receipt is the only readiness authority used here.

const RECEIPT_RPC = 'quote_walk_v2_operator_receipt';
const CLAIM_RPC = 'quote_walk_v2_consume_handoff_receipt';
const SEEN_RPC = 'quote_walk_v2_mark_operator_notification_seen';

function text(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function list(value) {
  return Array.isArray(value) ? value.filter(Boolean).map(String) : [];
}

function object(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function optionalObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : null;
}

function hasOwn(value, key) {
  return Object.prototype.hasOwnProperty.call(value, key);
}

function usdFromCents(value) {
  const cents = Number(value);
  if (!Number.isInteger(cents) || cents < 0) return null;
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: cents % 100 === 0 ? 0 : 2,
    maximumFractionDigits: cents % 100 === 0 ? 0 : 2,
  }).format(cents / 100);
}

function normalizeAddress(value) {
  const address = object(value);
  const enteredAddress = text(address.entered_address) || null;
  const county = text(address.service_area_county) || null;
  return {
    ...address,
    entered_address: enteredAddress,
    service_area_county: county,
    formatted_address: enteredAddress,
    county,
    service_area_status: text(address.service_area_status) || null,
    provenance: text(address.provenance) || null,
  };
}

function normalizePanel(value) {
  const panel = object(value);
  return {
    ...panel,
    provenance: text(panel.provenance) || null,
  };
}

function normalizeMedia(value) {
  const media = object(value);
  const analysis = optionalObject(media.analysis);
  const hasSupersededVersion = hasOwn(media, 'superseded_version');
  const supersededVersion = hasSupersededVersion
    ? media.superseded_version ?? null
    : null;
  return {
    ...media,
    role: text(media.role) || null,
    kind: text(media.role) || null,
    superseded_version: supersededVersion,
    active: hasSupersededVersion ? supersededVersion == null : null,
    status: hasSupersededVersion
      ? (supersededVersion == null ? 'active' : 'superseded')
      : null,
    provenance: text(media.provenance) || null,
    analysis: analysis
      ? {
          ...analysis,
          panelVisible: typeof analysis.panel_visible === 'boolean'
            ? analysis.panel_visible
            : null,
          analyzerVersion: text(analysis.analyzer_version) || null,
          provenance: text(analysis.provenance) || null,
        }
      : null,
  };
}

function normalizeRange(value) {
  const range = object(value);
  const current = optionalObject(range.current);
  const prior = optionalObject(range.prior);
  const low = current ? usdFromCents(current.low_cents) : null;
  const high = current ? usdFromCents(current.high_cents) : null;
  return {
    ...range,
    current,
    prior,
    revisions: Array.isArray(range.revisions) ? [...range.revisions] : [],
    display: low && high ? `${low} to ${high}` : null,
    pricing_basis: current ? text(current.pricing_basis) || null : null,
    status: current
      ? (text(current.invalidated_at) ? 'invalidated' : 'current')
      : null,
    provenance: text(range.provenance) || null,
  };
}

function normalizeGuide(value) {
  const guide = object(value);
  const earnedAt = text(guide.earned_at) || null;
  const href = text(guide.href) || null;
  const sha256 = text(guide.sha256) || null;
  const available = guide.available === true
    && Boolean(earnedAt && href && sha256);
  return {
    ...guide,
    earned_at: earnedAt,
    href,
    sha256,
    available,
    status: available ? 'earned' : 'unavailable',
    bound_at: earnedAt,
    provenance: text(guide.provenance) || null,
  };
}

function canonicalJson(value) {
  if (Array.isArray(value)) return value.map(canonicalJson);
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.keys(value).sort().map(key => [key, canonicalJson(value[key])])
    );
  }
  return value;
}

function sameJson(left, right) {
  return JSON.stringify(canonicalJson(left)) === JSON.stringify(canonicalJson(right));
}

export function quoteWalkV2ReceiptVerdict(receipt) {
  if (!receipt || typeof receipt !== 'object') {
    return {
      ready: false,
      state: 'missing',
      blockers: ['authoritative_receipt_missing'],
      message: 'Quote Walk readiness has not been verified.',
    };
  }
  if (receipt.error) {
    return {
      ready: false,
      state: 'error',
      blockers: ['authoritative_receipt_unavailable'],
      message: 'Quote Walk readiness could not be loaded.',
    };
  }

  const readiness = receipt.readiness;
  if (!readiness || typeof readiness !== 'object') {
    return {
      ready: false,
      state: 'invalid',
      blockers: ['authoritative_readiness_missing'],
      message: 'Quote Walk readiness is incomplete.',
    };
  }

  const blockers = list(readiness.handoff_blockers);
  const inputBlockers = list(readiness.input_blockers);
  const allBlockers = [...new Set([...blockers, ...inputBlockers])];
  if (receipt.handoff_status === 'claimed' || receipt.handoff_status === 'completed') {
    return {
      ready: false,
      state: 'history',
      blockers: [],
      message: receipt.handoff_status === 'completed'
        ? 'Quote Walk handoff is complete and available as read-only history.'
        : 'Quote Walk handoff has been claimed and is available as read-only history.',
    };
  }
  const identityComplete = Boolean(
    text(receipt.pre_read_id)
      && text(receipt.handoff_id)
      && receipt.readiness_receipt
      && typeof receipt.readiness_receipt === 'object'
      && text(readiness.snapshot_id)
      && text(readiness.acceptance_id)
      && Number.isInteger(Number(readiness.journey_version))
  );
  const ready = readiness.ready_for_handoff === true
    && receipt.consumable === true
    && identityComplete
    && allBlockers.length === 0;

  if (ready) {
    return {
      ready: true,
      state: 'ready',
      blockers: [],
      message: 'Quote Walk is ready for Quote Desk.',
    };
  }

  const stale = receipt.handoff_id
    && receipt.handoff_status === 'ready'
    && readiness.ready_for_handoff !== true;
  return {
    ready: false,
    state: stale ? 'stale' : 'incomplete',
    blockers: allBlockers.length ? allBlockers : ['authoritative_readiness_incomplete'],
    message: stale
      ? 'Quote Walk changed after this handoff. A current acceptance is required.'
      : 'Quote Walk still has required steps.',
  };
}

export function quoteWalkV2ReceiptMode(receipt) {
  if (receipt && typeof receipt === 'object' && receipt.readiness
      && typeof receipt.readiness === 'object') {
    return 'v2';
  }
  if (receipt && typeof receipt === 'object'
      && text(receipt.error).toLowerCase() === 'not_found') {
    return 'legacy';
  }
  return 'unavailable';
}

export function quoteWalkV2QuoteDeskState(receipt, legacyReady = false) {
  const mode = quoteWalkV2ReceiptMode(receipt);
  if (mode === 'legacy') {
    return {
      mode,
      visible: legacyReady === true,
      actionable: legacyReady === true,
      verdict: {
        ready: legacyReady === true,
        state: legacyReady === true ? 'legacy_ready' : 'legacy_incomplete',
        blockers: legacyReady === true ? [] : ['legacy_readiness_incomplete'],
        message: legacyReady === true
          ? 'Legacy Quote Desk readiness is available.'
          : 'Legacy quote details are incomplete.',
      },
    };
  }

  const verdict = quoteWalkV2ReceiptVerdict(receipt);
  return {
    mode,
    visible: verdict.state !== 'history',
    actionable: verdict.ready === true,
    verdict,
  };
}

export function quoteWalkV2OperatorProjection(receipt) {
  const mode = quoteWalkV2ReceiptMode(receipt);
  if (mode !== 'v2') {
    return {
      availability: mode,
      mode,
      error: mode === 'unavailable' ? text(receipt && receipt.error) || null : null,
    };
  }

  const journey = object(receipt.journey);
  const blockers = object(receipt.blockers);
  const nextAction = object(receipt.next_action);
  const setup = object(receipt.setup);
  const address = normalizeAddress(receipt.address);
  const range = normalizeRange(receipt.range);
  const reminder = object(receipt.reminder);
  const handoff = object(receipt.handoff);
  const operatorNotification = object(receipt.operator_notification);
  const history = receipt.handoff_status === 'claimed'
    || receipt.handoff_status === 'completed'
    || handoff.read_only_history === true;

  return {
    availability: 'available',
    mode,
    projectionVersion: text(receipt.projection_version) || null,
    identity: {
      preReadId: text(receipt.pre_read_id) || null,
      contactId: text(receipt.contact_id) || null,
    },
    journey: {
      version: journey.version ?? null,
      status: text(journey.status) || null,
      stage: text(journey.stage) || null,
      currentStep: text(journey.current_step) || null,
      lastActivityAt: text(journey.last_activity_at) || null,
    },
    blockers: {
      input: list(blockers.input),
      handoff: list(blockers.handoff),
      all: list(blockers.all),
      next: text(blockers.next) || null,
      provenance: text(blockers.provenance) || null,
    },
    nextAction: {
      key: text(nextAction.key) || null,
      sourceBlocker: text(nextAction.source_blocker) || null,
      provenance: text(nextAction.provenance) || null,
    },
    setup: {
      observedConnections: list(setup.observed_connections),
      pricingBasis: text(setup.pricing_basis) || null,
      panelLocationStatus: text(setup.panel_location_status) || null,
      panelLocation: text(setup.panel_location) || null,
      distanceBand: text(setup.distance_band) || null,
      cordIncluded: typeof setup.cord_included === 'boolean'
        ? setup.cord_included
        : null,
      provenance: text(setup.provenance) || null,
    },
    address,
    panels: Array.isArray(receipt.panels)
      ? receipt.panels.map(normalizePanel)
      : [],
    media: Array.isArray(receipt.media)
      ? receipt.media.map(normalizeMedia)
      : [],
    range,
    acceptance: receipt.acceptance || null,
    guide: normalizeGuide(receipt.guide),
    handoff: receipt.handoff || null,
    operatorNotification: {
      id: text(operatorNotification.id) || null,
      handoffId: text(operatorNotification.handoff_id) || null,
      status: text(operatorNotification.status) || null,
      providerMode: text(operatorNotification.provider_mode) || null,
      createdAt: text(operatorNotification.created_at) || null,
      seenAt: text(operatorNotification.seen_at) || null,
      provenance: text(operatorNotification.provenance) || null,
    },
    history,
    actionable: quoteWalkV2ReceiptVerdict(receipt).ready === true,
    reminder: {
      track: object(reminder.track),
      latestReceipt: object(reminder.latest_receipt),
      suppression: object(reminder.suppression),
    },
    humanEngagement: object(receipt.human_engagement),
    heldConfirmation: receipt.held_confirmation || null,
  };
}

export function quoteWalkV2OperatorDisplay(projection) {
  if (!projection || projection.availability !== 'available') {
    return {
      status: 'Unavailable',
      nextAction: 'Authoritative Quote Walk details are unavailable.',
      history: false,
    };
  }
  const stage = text(projection.journey && projection.journey.stage);
  const status = text(projection.journey && projection.journey.status);
  const nextAction = text(projection.nextAction && projection.nextAction.key);
  return {
    status: stage || status || 'Quote Walk',
    nextAction: projection.history === true ? 'none' : nextAction || 'none',
    history: projection.history === true,
  };
}

export async function fetchQuoteWalkV2OperatorReceipt(db, preReadId) {
  if (!db || typeof db.rpc !== 'function') {
    return { error: 'operator_database_unavailable' };
  }
  if (!text(preReadId)) {
    return { error: 'pre_read_id_missing' };
  }
  try {
    const result = await db.rpc(RECEIPT_RPC, { p_pre_read_id: preReadId });
    if (result && result.error) {
      return { error: text(result.error.message) || 'operator_receipt_failed' };
    }
    return result && result.data ? result.data : { error: 'operator_receipt_missing' };
  } catch (error) {
    return { error: text(error && error.message) || 'operator_receipt_failed' };
  }
}

export function quoteWalkV2ClaimRequestKey(handoffId) {
  const id = text(handoffId);
  if (!id) return '';
  return `quote-desk-claim:${id}`;
}

export async function markQuoteWalkV2OperatorNotificationSeen(db, receipt) {
  const notification = object(receipt && receipt.operator_notification);
  const handoffId = text(receipt && receipt.handoff_id);
  if (!handoffId || text(notification.handoff_id) !== handoffId) {
    return { ok: false, error: 'operator_notification_identity_missing' };
  }
  if (text(notification.status) !== 'unread') {
    return { ok: true, notification, skipped: true };
  }
  if (!db || typeof db.rpc !== 'function') {
    return { ok: false, error: 'operator_database_unavailable' };
  }
  let result;
  try {
    result = await db.rpc(SEEN_RPC, { p_handoff_id: handoffId });
  } catch (error) {
    result = { error };
  }
  if (result && result.error) {
    return {
      ok: false,
      error: text(result.error.message) || 'operator_notification_seen_failed',
    };
  }
  const updated = result && result.data;
  if (!updated
      || text(updated.handoff_id) !== handoffId
      || !['seen', 'claimed', 'completed'].includes(text(updated.status))) {
    return { ok: false, error: 'operator_notification_seen_mismatch' };
  }
  return { ok: true, notification: updated, skipped: false };
}

export async function consumeQuoteWalkV2HandoffReceipt(db, receipt) {
  const verdict = quoteWalkV2ReceiptVerdict(receipt);
  if (!verdict.ready) {
    return { ok: false, error: verdict.message, verdict };
  }
  if (!db || typeof db.rpc !== 'function') {
    return {
      ok: false,
      error: 'Quote Desk connection is unavailable.',
      verdict: {
        ready: false,
        state: 'error',
        blockers: ['operator_database_unavailable'],
        message: 'Quote Walk handoff could not be claimed.',
      },
    };
  }

  const requestKey = quoteWalkV2ClaimRequestKey(receipt.handoff_id);
  let result;
  try {
    result = await db.rpc(CLAIM_RPC, {
      p_pre_read_id: receipt.pre_read_id,
      p_handoff_id: receipt.handoff_id,
      p_request_key: requestKey,
    });
  } catch (error) {
    result = { error };
  }
  if (result && result.error) {
    return {
      ok: false,
      error: text(result.error.message) || 'handoff_claim_failed',
      verdict: {
        ready: false,
        state: 'error',
        blockers: ['handoff_claim_failed'],
        message: 'Quote Walk handoff could not be claimed.',
      },
    };
  }

  const claim = result && result.data;
  const identityMatches = claim
    && claim.ok === true
    && claim.pre_read_id === receipt.pre_read_id
    && claim.handoff_id === receipt.handoff_id
    && claim.snapshot_id === receipt.readiness.snapshot_id
    && claim.acceptance_id === receipt.readiness.acceptance_id
    && Number(claim.journey_version) === Number(receipt.readiness.journey_version)
    && sameJson(claim.readiness_receipt, receipt.readiness_receipt)
    && claim.handoff_status === 'claimed';
  if (!identityMatches) {
    return {
      ok: false,
      error: 'Quote Walk handoff receipt did not match the current accepted journey.',
      verdict: {
        ready: false,
        state: 'stale',
        blockers: ['handoff_receipt_mismatch'],
        message: 'Quote Walk changed after this handoff. A current acceptance is required.',
      },
    };
  }
  return { ok: true, claim, requestKey };
}

export async function fetchQuoteWalkV2ReceiptMap(db, preReadsByContact) {
  const entries = Object.entries(preReadsByContact || {});
  const resolved = await Promise.all(entries.map(async ([contactId, preRead]) => {
    const preReadId = preRead && preRead.id;
    const receipt = await fetchQuoteWalkV2OperatorReceipt(db, preReadId);
    return [contactId, receipt];
  }));
  return Object.fromEntries(resolved);
}
